```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::http_client;
use aap::caps::notifier;
use wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let now = wall_clock::now();

        // A transport failure is a value; the report then records zero characters.
        // A request outside the allowlist traps at the boundary and never reaches here.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!(
            "heartbeat: fetched {} chars from {} at {}",
            fetched, feed_url, now.seconds
        );
        let accepted = notifier::notify(&message);

        // The contract requires notified == true on every output. If the channel
        // refuses the notification, no conforming output exists, so trap rather
        // than return a report with notified == false.
        if !accepted {
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified: true,
        }
    }
}

export!(Node);
